/// The outcome of a [`Guardrail::check`].
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum GuardrailVerdict {
    /// All clear — the run continues.
    Pass,
    /// Tripwire fired — the run halts and the runner emits a corresponding
    /// agent event.
    Tripwire {
        /// Which kind of tripwire fired.
        kind: GuardrailKind,
